#!/bin/bash
# Compile every source named by tools/sources.txt of the Ath12kWifi checkout for
# arm64-apple, and record what came out. Nothing here links: the point of this
# step is to prove that the 125 objects the stack's own audit counts are the
# same 125 objects a clean macOS toolchain produces, before any of them are
# handed to the kernel link.
#
# Usage: tools/fuxi-ath12k-build.sh ATH12K_ROOT OUT_DIR
#
# ATH12K_ROOT must already contain deps/linux and deps/wpa_supplicant-2.12 (the
# caller stages them from pinned archives) and out/ generated by tools/prepare.sh.
set -euo pipefail

[[ $# == 2 ]] || { echo 'usage: fuxi-ath12k-build.sh ATH12K_ROOT OUT_DIR' >&2; exit 2; }
M=$(cd "$1" && pwd)
OUT=$2
[[ -f $M/tools/sources.txt ]] || { echo "no tools/sources.txt under $M" >&2; exit 2; }
mkdir -p "$OUT/objects" "$OUT/logs"

clang=$(xcrun --find clang)
resource=$("$clang" -print-resource-dir)
echo "clang=$clang"
echo "resource=$resource"
"$clang" --version | head -1

# -nostdinc + shim/libc keeps the host's libc headers out: the stack brings its
# own declarations, and a Linux errno.h reaching out/pinned is what made the
# first local attempt fail with "use of undeclared identifier 'EINVAL'".
BASE="-c -target arm64-apple-macos13 -nostdinc -isystem $M/shim/libc -isystem $resource/include \
    -std=gnu11 -w -g0 -O2 -DCONFIG_ATH12K_DEBUG \
    -DCONFIG_MAC80211_STA_HASH_MAX_SIZE=0 -DCONFIG_CFG80211=1 -DCONFIG_MAC80211=1 \
    -DCONFIG_MAC80211_RC_DEFAULT=\"\" \
    -include lx_pci.h \
    -I $M/shim/include -I $M/include -I $M/out/pinned -I $M/shim/crypto -I $M/out -I $M/src \
    -I $M/out/mac80211 -I $M/out/mhi-src -I $M/out/crypto"
# sock_release is declared in shim/include/lx_net.h, defined in src/nw_qrtr.c and
# called from the staged qmi_interface.c, so the stack is self-consistent -- but
# the kernel exports sock_release too. Rename it across the whole stack so the
# kernel's BSD socket entry point keeps its name.
BASE="$BASE -Dsock_release=nw_sock_release"
# Module units (src/*.c, the generated bodies, the shim) mean cfg80211's core.h.
MODULE="$BASE -I $M/out/cfg80211 -I $M/out/ath12k-src -I $M/out/ath12k-src/wifi7"
# ath12k units mean their own core.h.
ATH12K="$BASE -I $M/out/ath12k-src -I $M/out/ath12k-src/wifi7 -I $M/out/cfg80211"
# src/nw_debug.c is the one module unit that names ath12k's own core.h and
# debug.h. BASE lists out/mac80211 before out/ath12k-src, so "debug.h" resolves
# to mac80211's copy (guard __MAC80211_DEBUG_H) and enum ath12k_debug_mask never
# appears; only this unit needs the ath12k tree first.
ATH12K_FIRST="-I $M/out/ath12k-src -I $M/out/ath12k-src/wifi7 $ATH12K"
# src/nw_fils.c calls nw_aes_siv_encrypt/decrypt while the supplicant's aes-siv.c
# defines aes_siv_encrypt/decrypt. The rename has to stay on the crypto units:
# applied to nw_fils.c it also renames that file's own static definition and the
# build fails on a conflicting declaration. aes_encrypt/init/deinit are renamed
# for the same reason as sock_release -- the kernel exports them.
CRYPTO="$MODULE -Daes_siv_encrypt=nw_aes_siv_encrypt -Daes_siv_decrypt=nw_aes_siv_decrypt \
    -Daes_encrypt=nw_aes_encrypt -Daes_encrypt_init=nw_aes_encrypt_init \
    -Daes_encrypt_deinit=nw_aes_encrypt_deinit"

resolve() {
    case "$1" in
        ath12k:*) echo "$M/out/ath12k-src/${1#ath12k:}" ;;
        mac80211:*) echo "$M/out/mac80211/${1#mac80211:}" ;;
        cfg80211:*) echo "$M/out/cfg80211/${1#cfg80211:}" ;;
        mhi:*) echo "$M/out/mhi-src/${1#mhi:}" ;;
        qmi:*) echo "$M/deps/linux/drivers/soc/qcom/${1#qmi:}" ;;
        crypto:*) echo "$M/out/crypto/${1#crypto:}" ;;
        generated:*) echo "$M/out/${1#generated:}" ;;
        *) echo "$M/$1" ;;
    esac
}

: > "$OUT/ath12k-objects.txt"
: > "$OUT/ath12k-failures.txt"
ok=0 fail=0 skipped=0
while IFS= read -r line; do
    line=${line%%#*}; line=$(echo "$line" | tr -d '[:space:]')
    [[ -z $line ]] && continue
    src=$(resolve "$line")
    # Name the object after the sources.txt label, not the basename: ath12k/ce.c
    # and ath12k:wifi7/ce.c both basename to "ce", and a basename scheme silently
    # overwrote 19 objects the first time this was run.
    name=$(printf '%s' "$line" | tr ':/' '__')
    if [[ ! -f $src ]]; then
        skipped=$((skipped + 1)); echo "SKIP $line (missing $src)" | tee -a "$OUT/ath12k-failures.txt"
        continue
    fi
    case "$line" in
        ath12k:*) flags=$ATH12K ;;
        crypto:*) flags=$CRYPTO ;;
        *) flags=$MODULE ;;
    esac
    if "$clang" $flags "$src" -o "$OUT/objects/$name.o" 2> "$OUT/logs/$name.err"; then
        ok=$((ok + 1))
        printf '%s %s %s\n' "$name" "$line" "$(shasum -a 256 "$OUT/objects/$name.o" | cut -d' ' -f1)" >> "$OUT/ath12k-objects.txt"
    elif "$clang" $ATH12K_FIRST "$src" -o "$OUT/objects/$name.o" 2> "$OUT/logs/$name.err"; then
        ok=$((ok + 1)); echo "RETRY $line (ath12k headers first)"
        printf '%s %s %s\n' "$name" "$line" "$(shasum -a 256 "$OUT/objects/$name.o" | cut -d' ' -f1)" >> "$OUT/ath12k-objects.txt"
    else
        fail=$((fail + 1))
        echo "FAIL $line :: $(grep -m1 'error:' "$OUT/logs/$name.err" | cut -c1-200)" | tee -a "$OUT/ath12k-failures.txt"
    fi
done < "$M/tools/sources.txt"

objects=$(ls -1 "$OUT/objects" | wc -l | tr -d ' ')
echo "ATH12K_BUILD ok=$ok fail=$fail skipped=$skipped objects=$objects"

# Undefined and defined symbols, so the link audit can run against the artifact
# without rebuilding. llvm-nm reads Mach-O; GNU nm does not.
nm=$(xcrun --find llvm-nm)
"$nm" -j --undefined-only "$OUT/objects"/*.o | sed 's/^_//' | sort -u > "$OUT/ath12k-undefined.txt"
"$nm" -j --defined-only "$OUT/objects"/*.o | sed 's/^_//' | sort -u > "$OUT/ath12k-defined.txt"
# What the stack wants from outside itself: undefined minus everything any of its
# own objects defines. Without this subtraction the list is dominated by internal
# names (lx_*, ath12k_*, nw_*) and a gap against kernel exports is meaningless.
comm -23 "$OUT/ath12k-undefined.txt" "$OUT/ath12k-defined.txt" > "$OUT/ath12k-external.txt"
# shim/libc provides these at link time. They are not kernel dependencies in the
# strict sense, but the kernel exports most of them too, so the audit reports the
# external set both ways rather than picking one and calling it the truth.
printf '%s\n' memcpy memmove memset memcmp strlen strcmp strncmp strncpy strlcpy \
    snprintf vsnprintf strtoul bzero abort | sort -u > "$OUT/ath12k-libc.txt"
comm -23 "$OUT/ath12k-external.txt" "$OUT/ath12k-libc.txt" > "$OUT/ath12k-needs-kernel.txt"
printf 'undefined=%s defined=%s external=%s libc=%s needs-kernel=%s\n' \
    "$(wc -l < "$OUT/ath12k-undefined.txt" | tr -d ' ')" \
    "$(wc -l < "$OUT/ath12k-defined.txt" | tr -d ' ')" \
    "$(wc -l < "$OUT/ath12k-external.txt" | tr -d ' ')" \
    "$(wc -l < "$OUT/ath12k-libc.txt" | tr -d ' ')" \
    "$(wc -l < "$OUT/ath12k-needs-kernel.txt" | tr -d ' ')"

# Which object defines which global. --defined-only -g keeps external linkage
# only, so file-local helpers (l_.str.N, "input") stay out of the collision
# check: they cannot clash with a kernel symbol by construction.
: > "$OUT/ath12k-globals.txt"
for o in "$OUT/objects"/*.o; do
    "$nm" -g -j --defined-only "$o" | sed 's/^_//' | while IFS= read -r sym; do
        printf '%s\t%s\n' "$sym" "$(basename "$o")"
    done >> "$OUT/ath12k-globals.txt"
done
printf 'globals=%s\n' "$(cut -f1 "$OUT/ath12k-globals.txt" | sort -u | wc -l | tr -d ' ')"

[[ $fail == 0 && $skipped == 0 ]] || { echo "ath12k objects did not all build" >&2; exit 1; }
